SELECT 'moj-all-verified-judgments-review-002-chunk-077' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e11894ab-edcd-5a13-b976-b01aa417fffc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -حيازة بقصد التعاطي واالجتار -هروب من رجال األمن -اإلقرار -كبر الكمية املضبوطة -تداخل العقوبات -التعزير بالسجن والغرامة واملنع من السفر .","document_number":"34368151","case_number":"34523805","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/25","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -حيازة بقصد التعاطي واالجتار -هروب من رجال األمن -اإلقرار -كبر الكمية املضبوطة -تداخل العقوبات -التعزير بالسجن والغرامة واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34368151:‬تاريخه‪1434/11/25:‬هـ‬\n                          ‫رقم الدعوى‪34523805:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34386957‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬حيــازة بقصــد التعاطــي‬\n       ‫واالجتــار ‪ -‬هــروب مــن رجــال األمــن ‪ -‬اإلقــرار ‪-‬كبــر الكميــة املضبوطــة‬\n       ‫‪ -‬تداخــل العقوبــات ‪ -‬التعزيــر بالســجن والغرامــة واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n        ‫‪-1‬قوله صلى اهلل عليه وسلم ( كل مسكر خمر وكل خمر حرام ) ‪.‬‬\n       ‫‪-2‬جــاء يف كشــاف القنــاع ج‪( 85/6‬وإن لــم يكــن فيهــا ‪ -‬أي حــدود اهلل ‪-‬‬\n       ‫القتــل فــإن كانــت مــن جنــس واحــد مثــل أن يزنــي مــرارا أو يســرق مرارا‬\n       ‫أو يشــرب اخلمــر مــرارا قبــل إقامــة احلــد أجــزأ حــد واحــد فتتداخــل‬\n                                                          ‫الســرقة كغيرهــا ‪ ..‬إلــخ)‬\n                                     ‫‪-3‬قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374‬هـ ‪.‬‬\n       ‫‪-4‬املــادة األولــى فقــرة (د) مــن قــرار وزيــر الداخليــة رقــم (‪ )2057‬يف‬\n                                                                       ‫‪1404/5/26‬ه ـ ‪.‬‬\n        ‫‪-5‬املادة الثالثة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪ 1404/5/26‬هـ‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد االســتعمال‬\n       ‫الشــخصي ونقــل قــات بقصــد الترويــج وهروبــه مــن رجــال األمــن ‪،‬طلــب‬\n\n‫‪493‬‬\n\f‫إثبــات مــا أســند إليــه ومعاقبتــه تعزيــر ًا ومصــادرة ســيارته وفــق األنظمــة‬\n‫والتعليمــات ‪،‬حيــث جــرى االشــتباه بالســيارة التــي يقودهــا املدعــى عليــه‬\n‫وطلــب منــه الوقــوف مــن الدوريــة األمنيــة ولــم يتوقــف ومبتابعتــه أوقــف‬\n‫الســيارة وهــرب منهــا وبتفتيــش الســيارة عثــر فيهــا علــى نبــات القــات‬\n‫وأثبــت التقريــر الكيميائــي إيجابيــة العينــة املضبوطــة لنبــات القــات‬\n‫احملظــور ‪،‬ويف يــوم آخــر عنــد نقطــة التفتيــش جــرى االشــتباه بالســيارة‬\n‫التــي يقودهــا املدعــى عليــه فجــرى اســتيقافه وبتفتيــش الســيارة عثــر‬\n‫علــى نبــات القــات واعتــرف املدعــى عليــه حتقيق ـ ًا بحيــازة القــات يف‬\n‫املــرة األولــى وأن قصــده نقلهــا لشــخص آخــر مقابــل مبلــغ مالــي وأن‬\n‫الكميــة املضبوطــة يف املــرة الثانيــة لالســتعمال الشــخصي ‪،‬وصــادق‬\n‫املدعــى عليــه علــى الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n‫بســجنه تعزيــرا خمــس ســنوات وغرامــة ماليــة قدرهــا خمســة آالف‬\n‫ريــال ومنعــه مــن الســفر بعــد انتهــاء محكوميتــه ورد الدعــوى مبطالبــة‬\n‫مصــادرة الســيارة وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫الئحــة ُ‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪ .....‬القاضــي يف احملكمــة اجلزائيــة بجــازان وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪34523805‬‬\n‫وتاريــخ ‪ 1434/11/23‬ه ـ املقيــدة باحملكمــة برقــم ‪342654031‬‬\n‫وتاريــخ ‪1434/11/23‬ه ـ ففــي يــوم اإلثنــن املوافق‪1434/11/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة صباح ـ ًا وفيهــا حضــر املدعــي العــام‬\n\n                                                                                      ‫‪494‬‬\n\f      ‫‪.....‬املعمــد بالعمــل مبوجــب خطــاب رقــم ‪.....‬وتاريــخ ‪1434/08/29‬ه ـ‬\n      ‫وحضــر املدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ا يف دعــواه أنــه بتاريــخ ‪1431/12/13‬هـ‬       ‫(‪ ).....‬وادعــى املدعــي العــام قائـ ً‬\n      ‫وأثنــاء قيــام دوريــات حــرس احلــدود بقطــاع الدايــر مركــز ‪.....‬بعملهــا‬\n      ‫شــاهدت ســيارة نــوع ‪ .....‬ســنة صنعهــا ‪1983‬م حتمــل اللوحــة رقــم (‪).....‬‬\n      ‫(تعــود ملكيتهــا للمدعــى عليــه املذكــور أعــاه) وعنــد االشــتباه بهــا مت‬\n      ‫اســتيقاف قائدهــا و لــم ميتثــل بالوقــوف ومبتابعتــه قــام بإيقــاف الســيارة‬\n      ‫والهــرب منهــا وبتفتيــش الســيارة عثــر فيهــا علــى كميــة مــن مــادة القــات‬\n      ‫احملظــور وقــد بلــغ وزن مــا مت العثــور عليــه (‪ 506‬كجــم) خمــس مائــة‬\n      ‫وســتة كيلــو جــرام وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n      ‫يف ‪1431/12/24‬ه ـ ايجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور‬\n      ‫ويف متــام الســاعة ‪ 12.30‬مــن مســاء يــوم اإلثنــن املوافــق ‪1426/8/9‬ه ـ‬\n      ‫وأثنــاء قيــام دوريــات املجاهديــن بعملهــا بنقطــة التفتيــش مبركــز ‪.......‬‬\n      ‫مت إســتيقاف ســيارة نــوع ‪ ........‬ســنة صنعهــا ‪1998‬م حتمــل اللوحــة رقــم‬\n      ‫(‪ ).....‬تعــود ملكيتهــا للمدعــى عليــه وبقيادتــه وبتفتيــش الســيارة مت‬\n      ‫العثــور علــى كيــس بــه نبــات يشــتبه أن يكــون من نبات القــات احملظور‬\n      ‫بلــغ وزنــه (‪ 9‬كجــم) تســعة كيلــو جــرام وقــد أثبــت التقريــر الكيميائي‬\n      ‫الشــرعي رقــم (‪ ).....‬بتاريــخ ‪1434/8/17‬ه ـ إيجابيــة العينــة املرســلة‬\n      ‫منــه لنبــات القــات احملظــور وباســتجواب املدعــى عليــه بعــد مواجهتــه‬\n      ‫بالتهمــة املنســوبة إليــه أقــر بحيازتــه للكميــة األولــى وأن غرضــه مــن‬\n      ‫حيــازة الكميــة نقلهــا لشــخص ال يعرفــه مــن ‪.....‬إلــى قريــة ‪.....‬مقابــل‬\n      ‫مبلــغ وقــدره (‪ )10.000‬عشــرة آالف ريــال وأقــر بقيامــه بالهــرب مــن‬\n      ‫رجــال األمــن وبســماع أقوالــه مــن قبــل جهــة اإلســتدالل بشــأن الكميــة‬\n\n\n‫‪495‬‬\n\f‫الثانيــة أقــر بحيازتــه الكميــة وذكــر بأنــه اشــتراها مــن شــخص ال‬\n‫يعرفــه مقابــل ‪ 1000‬ريــال وغرضــه مــن حيازتهــا االســتخدام الشــخصي‬\n‫وقــد مت االكتفــاء مبــا جــاء يف محضــر ســماع أقوالــه اســتنادا للمــادة‬\n‫(‪ )64‬مــن نظــام اإلجــراءات اجلزائيــة وقــد أســفر التحقيــق عــن اتهــام‪/‬‬\n‫‪.....‬بنقــل (‪ 506‬كجــم) خمــس مائــة وســتة كيلــو جــرام مــن نبــات القــات‬\n‫احملظــور بقصــد االجتــار وحيــازة (‪ 9‬كجــم) تســعة كيلــو جــرام بقصــد‬\n‫االســتخدام الشــخصي واملجــرم مبوجــب الفقــرة (‪ )2‬مــن املــادة (الثالثــة)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وهروبــه مــن رجــال األمــن‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا و معاقــب عليــه‬\n‫نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا‬\n‫حلــق بــه مــن تعديــات ‪ ،‬لــذا أطلــب‪-1 :‬إثبــات إدانتــه مبــا أســند إليــه‬\n‫واحلكــم بتعزيــره يف ضــوء املــادة (الثالثــة والرابعــة) مــن القــرار الــوزاري‬\n‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ ‪-2‬مصــادرة الســيارة ســنة صنعهــا ‪1983‬م حتمــل اللوحة‬\n‫رقــم (‪ ).....‬رقــم الهيــكل (‪ ).....‬املســتخدمة يف عمليــة النقــل وفقــا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املشــار إليــه وإيــداع قيمتهــا يف حســاب اإلدارة العامــة ملكافحــة‬\n‫املخــدرات وفقــا لقــرار مجلــس الوزراء رقــم (‪ )47‬وتاريخ ‪1421/2/18‬هـ‬\n‫وقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويته وأهليته جرى ســؤاله‬\n‫عــن الدعــوى فأجــاب قائــا إن مــا ذكــره املدعــي العــام مــن اتهامي بنقل‬\n‫مــا وزنــه (‪506‬كجــم) خمســمائة وســتة كيلــو مــن نبــات القــات بقصــد‬\n‫التجــارة وحيــازة مــا وزنــه (‪ 9‬كجــم ) تســعة كيلــو جــرام مــن القــات‬\n\n\n                                                                                      ‫‪496‬‬\n\f      ‫احملظــور بقصــد االســتعمال والتعاطــي فهــذا كلــه صحيــح هكــذا‬\n      ‫أجــاب فجــرى االطــاع علــى كامــل أوراق املعاملــة ومنهــا محضــر‬\n      ‫القبــض املرفــق باملعاملــة فوجدتــه يتضمــن القبــض علــى املدعــى عليــه‬\n      ‫وبحوزتــه الكميــة املذكــورة يف الدعــوى كمــا جــرى االطــاع علــى‬\n      ‫كــرت ســوابق املدعــى عليــه فلــم يعثــر لــه علــى ســوابق مســجلة كمــا‬\n      ‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه فوجــدت أنــه أوقــف‬\n      ‫بتاريــخ ‪1434/08/09‬ه ـ كمــا جــرى االطــاع على التقريــر الكيماوي‬\n      ‫الشــرعي املرفــق باملعاملــة الصــادر مــن مستشــفى امللــك فهــد املركــزي‬\n      ‫بجــازان برقم‪.....‬وتاريــخ ‪ 1431/12/24‬ه ـ فوجدتــه يتضمــن ايجابيــة‬\n      ‫العينــة للقــات احملظــورة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث اعتــرف املدعــى عليــه بحيــازة مــا وزنــه (‪506‬كجــم ) خمســمائة‬\n      ‫وســتة كيلــو جرامـ ًا مــن القــات احملظــور لقصــد االجتــار بهــا واعترافــه‬\n      ‫بحيــازة مــا وزنــه (‪9‬كجــم ) تســعة كيلــو جرامـ ًا مــن نبات القــات لقصد‬\n      ‫االســتعمال وحيــث ال توجــد ســوابق مســجلة عليــه وحيــث أثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي ايجابيــة العينــة للقــات احملظــور ومبــا أن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه مــن احملــرم شــرعا ملــا يف اســتعمال القــات وترويجــه‬\n      ‫بــن النــاس أضــرار بليغــة علــى الديــن و النفــس و العقــل والعــرض واملــال‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ‪ ( :‬كل مســكر خمــر وكل خمــر حــرام‬\n      ‫) ممــا يســتوجب إيقــاع العقوبــة علــى املدعــى عليــه ومبــا أن املدعــى‬\n      ‫عليــه جمــع بــن حيــازة للترويــج وحيــازة لقصــد االســتعمال وعقوبــة‬\n      ‫الترويــج أشــد ولــم يحكــم لــه يف أحدهمــا يف قضيــة منفصلــة عنهــا‬\n      ‫وهــي مــن جنســها ممــا يســتوجب تداخــل العقوبــات يف ذالــك ويعاقــب‬\n      ‫باألشــد منهمــا جــاء يف كشــاف القنــاع عــن مــن اإلقنــاع ص‪[ 6/85‬‬\n\n\n‫‪497‬‬\n\f‫وإن لــم يكــن فيهــا أي حــدود اهلل القتــل فــإن كانــت مــن جنــس مثــل‬\n‫أن يزنــي مــرارا أو يســرق مــرارا أو يشــرب اخلمــر مــرارا قبــل إقامــة احلــد‬\n‫أجــزء حــد واحــد فتتداخــل الســرقة كغيرهــا قــال ابــن منــذر ‪ ( :‬أجمــع‬\n‫حفــظ عنــه مــن أهــل العلــم وذلــك ألن الغــرض‬      ‫علــى هــذا كلــه مــن ُي َ‬\n‫الزجــر عــن إتيــان مثــل ذلــك يف املســتقبل وهــو حاصــل باحلــد الواحــد ]‬\n‫أ‪.‬ه ـ فتدخــل عقوبــة االســتعمال يف عقوبــة الترويــج لــذا كلــه وألجــل‬\n‫احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي أوال ‪ :‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بحيــازة مــا وزنــه (‪9‬كجــم ) تســعة كيلــو جرام ـ ًا للقــات‬\n‫احملظــور لقصــد االســتعمال والتعاطــي ‪ /‬ثانيــا ‪ :‬ثبــت لــدي إدانــة املدعــى‬\n‫عليــه بنقــل مــا وزنــه (‪506‬كجــم ) خمســمائة وســتة كيلــو جرام ـ ًا مــن‬\n‫نبــات القــات احملظــور لقصــد االجتــار بهــا ‪/‬ثالثــا حكمــت بســجنه‬\n‫ملــدة [ خمــس ســنوات ] حتتســب منهــا مــدة إيقافــه علــى ذمــة القضيــة‬\n‫وغرامــة ماليــة قدرهــا خمســة آالف ريــال وذلــك اســتنادا علــى القــرار‬\n‫الــوزاري رقــم (‪ )11‬وتاريــخ ‪ 1374/2/1‬ه ـ واملــادة الثالثــة مــن قــرار‬\n‫ســمو وزيــر الداخليــة رقــم (‪ ) 2057‬وتاريــخ ‪1404/05/26‬ه ـ ‪ /‬رابعــا‪:‬‬\n‫كمــا حكمــت مبنعــه مــن الســفر ملــدة [ خمــس ســنوات ] بعــد انتهــاء‬\n‫محكوميتــه اســتنادا للمــادة األولــى يف الفقــرة ( د ) مــن قــرار وزيــر‬\n‫الداخليــة رقــم (‪ ) 2057‬وتاريــخ ‪1404/05/26‬هــ‪/ .‬خامســا ‪ :‬كمــا‬\n‫حكمــت بــرد دعــوى املدعــي العــام بطلــب مصــادرة الســيارة املوصوفــة‬\n‫بالدعــوى وبعــرض احلكــم عليــه قــرر قناعتــه بــه كمــا قــرر املدعــي‬\n‫العــام معارضتــه علــى احلكــم وطلــب االســتئناف بــدون لالئحــة مكتفيــا‬\n‫مبــا قدمــه مــن أوراق عليــه فســيتم رفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف واختتمــت اجللســة الســاعة التاســعة والنصــف وبــاهلل التوفيــق‬\n\n\n                                                                                     ‫‪498‬‬\n\f      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر بتاريــخ‬\n                                                                ‫‪ 1434/11/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342654031‬وتاريــخ ‪1434 /12/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34369151‬وتاريــخ‬\n      ‫‪1434/11/25‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ــد ‪ ..... /‬يف قضيــة‬\n      ‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪499‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليهما حليازتهما‬\n                                                            ‫ترويج‬\n  ‫‪5‬‬      ‫وترويجهما حبوب اإلمفيتامني احملظورة وتعاطيهما‬               ‫‪1‬‬\n                                                           ‫مخدرات‬\n                             ‫من نوعها‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويجه الهيروين‬     ‫ترويج‬\n  ‫‪15‬‬                                                                 ‫‪2‬‬\n                ‫وتعاطيه وإلعداد منزله وكر ًا لذلك‬          ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهما‪ :‬األول لترويجه‬\n         ‫احلشيش وحيازته وعدد من حبوب الروش احملظورة‬         ‫ترويج‬\n  ‫‪28‬‬                                                                 ‫‪3‬‬\n         ‫بقصد التعاطي وتعاطيه للحبوب واحلشيش واآلخِ ر‬      ‫مخدرات‬\n             ‫بالتوسط يف ترويج احلشيش وحيازة قطعة منه‬\n\n\n           ‫دعوى عامة بتعزيز املدعى عليه (مقيم) لترويجه‬\n                                                            ‫ترويج‬\n  ‫‪42‬‬      ‫احلبوب احملظورة وتعاطيها وحيازة احلشيش بقصد‬                ‫‪4‬‬\n                                                           ‫مخدرات‬\n                         ‫التعاطي وتعاطيه‬\n\n\n         ‫دعوى عامة بتعزيراملدعى عليهما لترويجهما قطعة‬\n                                                            ‫ترويج‬\n  ‫‪50‬‬     ‫كبيرة من احلشيش وحليازة األول احلشيش واحلبوب‬                ‫‪5‬‬\n                                                           ‫مخدرات‬\n           ‫احملظورة بقصد الترويج والتعاطي وتعاطيهما‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهم (مقيم ومواطنني)‬\n            ‫لترويج األول والثاني للحشيش باإلهداء وترويج‬     ‫ترويج‬\n  ‫‪68‬‬                                                                 ‫‪6‬‬\n         ‫األول حبوب اإلمفيتامني والروش باإلهداء وتعاطيهم‬   ‫مخدرات‬\n              ‫للحشيش وتستر األول والثاني على املصدر‬\n\f‫الصفحة‬                      ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه ست حبات‬\n                                                             ‫ترويج‬\n  ‫‪81‬‬       ‫من حبوب اإلمفيتامني بالبيع وتعاطيه احلشيش‬                  ‫‪7‬‬\n                                                            ‫مخدرات‬\n                  ‫واحلبوب وتستره على املصدر‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهم ( منهم رجل أمن)‬\n                                                             ‫ترويج‬\n  ‫‪95‬‬     ‫للشروع يف استالم احلبوب احملظورة بقصد االجتار‬                ‫‪8‬‬\n                                                            ‫مخدرات‬\n             ‫وبيع احلشيش وحيازة املسكر وتعاطيهما‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لبيعه قطعة من‬         ‫ترويج‬\n ‫‪114‬‬                                                                  ‫‪9‬‬\n                    ‫احلشيش بقصد االجتار‬                     ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويجه ثالث‬          ‫ترويج‬\n ‫‪131‬‬                                                                  ‫‪10‬‬\n          ‫جرامات من احلشيش املخدر وتعاطيه للحشيش‬            ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهما لتعاطيهما‬\n                                                             ‫ترويج‬\n ‫‪139‬‬     ‫احلشيش وترويج األول لسيجارة مخلوطة باحلشيش‬                   ‫‪11‬‬\n                                                            ‫مخدرات‬\n         ‫باإلهداء لآلخِ ر وحيازة اآلخِ ر لها بقصد التعاطي‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لتسليمه ‪1,232‬‬         ‫ترويج‬\n ‫‪148‬‬                                                                  ‫‪12‬‬\n                ‫جرام ًا من القات وتعاطيه للقات‬              ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لبيعه عدد خمس‬         ‫ترويج‬\n ‫‪157‬‬                                                                  ‫‪13‬‬\n          ‫حبات من احلبوب املنبهة احملظورة بقصد االجتار‬      ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهما لتعاطي األول‬        ‫ترويج‬\n ‫‪165‬‬                                                                  ‫‪14‬‬\n             ‫احلشيش وترويجه وتوسط اآلخِ ر يف ذلك‬            ‫مخدرات‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه لترويجه حبوب‬      ‫ترويج‬\n ‫‪175‬‬                                                               ‫‪15‬‬\n           ‫اإلمفيتامني بقصد الكسب املادي وتعاطيه لها‬     ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه قطعة من‬\n                                                          ‫ترويج‬\n ‫‪183‬‬      ‫احلشيش وتعاطيه له وقيادته للسيارة حتت تأثيره‬             ‫‪16‬‬\n                                                         ‫مخدرات‬\n                       ‫وتستره على املصدر‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويج احلشيش‬      ‫ترويج‬\n ‫‪193‬‬                                                               ‫‪17‬‬\n          ‫وحيازته له بقصد الترويج والتعاطي وتعاطيه له‬    ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويجه احلبوب‬     ‫ترويج‬\n ‫‪201‬‬                                                               ‫‪18‬‬\n                     ‫احملظورة وتعاطيه لها‬                ‫مخدرات‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه لتسليم وحيازة‬     ‫ترويج‬\n ‫‪208‬‬                                                               ‫‪19‬‬\n              ‫الهيروين لغرض الترويج وشروعه يف ذلك‬        ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لنقله القات بقصد‬    ‫ترويج‬\n ‫‪215‬‬                                                               ‫‪20‬‬\n                            ‫االجتار‬                      ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهما (أجنبي وسعودي)‬    ‫ترويج‬\n ‫‪222‬‬                                                               ‫‪21‬‬\n           ‫باالشتراك يف بيع القات ومقاومة رجال األمن‬     ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويجه احلبوب‬     ‫ترويج‬\n ‫‪231‬‬                                                               ‫‪22‬‬\n                    ‫احملظورة عن طريق البيع‬               ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لترويجه احلبوب‬     ‫ترويج‬\n ‫‪238‬‬                                                               ‫‪23‬‬\n               ‫احملظورة وحيازة حبة وتعاطيه ملثلها‬        ‫مخدرات‬\n\f‫الصفحة‬                       ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهما لترويجهما احلبوب‬\n                                                            ‫ترويج‬\n ‫‪244‬‬     ‫احملظورة عن طريق البيع والتوسط يف ذلك وحيازة‬                ‫‪24‬‬\n                                                           ‫مخدرات‬\n                      ‫حبة منها وتعاطي مثلها