                        ‫‪48‬‬\n                    ‫وبيع قطعة من احلشيش‬                     ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه (مقيم) لتلقيه القات‬    ‫ترويج‬\n ‫‪445‬‬                                                                  ‫‪49‬‬\n                       ‫من اليمن بقصد الترويج‬                ‫مخدرات‬\n\f‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهما لبيعهما القات‬      ‫ترويج‬\n ‫‪449‬‬                                                                 ‫‪50‬‬\n          ‫بقصد الترويج واالجتار وتسترهما على املصدر‬        ‫مخدرات‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى عليه‬\n                                                            ‫ترويج‬\n ‫‪456‬‬     ‫وتعزيره لترويجه حبوب اإلمفيتامني وحيازة احلشيش‬              ‫‪51‬‬\n                                                           ‫مخدرات‬\n                    ‫بقصد التعاطي وتعاطيه له‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليهما لالشتراك‬\n                                                            ‫ترويج‬\n ‫‪467‬‬       ‫يف ترويج القات بقصد االجتار عن طريق النقل‬                 ‫‪52‬‬\n                                                           ‫مخدرات‬\n                      ‫وتسترهما على املروج‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لنقله القات بقصد‬\n                                                            ‫ترويج‬\n ‫‪474‬‬     ‫الترويج ولهروبه من رجال األمن والتسبب يف انقالب‬             ‫‪53‬‬\n                                                           ‫مخدرات‬\n           ‫سيارة الدورية بعد هروبه والتستر على املصدر‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه املخدرات‬      ‫ترويج‬\n ‫‪482‬‬                                                                 ‫‪54‬‬\n                 ‫(حبوب الكبتاجون احملظورة)‬                 ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه بالوساطة يف بيع‬      ‫ترويج‬\n ‫‪488‬‬                                                                 ‫‪55‬‬\n                      ‫القات بقصد الترويج‬                   ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته القات بقصد‬\n                                                            ‫ترويج‬\n ‫‪493‬‬      ‫االستعمال الشخصي ونقله القات بقصد الترويج‬                  ‫‪56‬‬\n                                                           ‫مخدرات‬\n                     ‫وهروبه من رجال األمن‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":493,"source_page_end":506,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8132679c55e476d294d1abc8946395eed1ff61c8845d37ebb6937541da2a6473","normalized_text_hash":"70136bf007cf9aa8f22800c00d59af805b3b02caa9d987cdf98d7d7554eaf1eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p493-34368151"},{"id":"da064407-7e77-5a4b-aa48-83ed256957cf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -تأجيل تنفيذ احلكم لكون املدعى عليه طالب ا -التعزير بالسجن واجللد واملنع من السفر .","document_number":"3412799","case_number":"2403","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1429/05/20","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -تأجيل تنفيذ احلكم لكون املدعى عليه طالب ا -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪3412799:‬تاريخه‪1429/05/20 :‬هـ‬\n                           ‫رقم الدعوى‪2403:‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34217997‬تاريخه‪1434/05/20 :‬هـ‬\n\n\n    ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬إقــرار‪ -‬إدانــة‪-‬‬\n    ‫نــزول عــن احلــد األدنــى للعقوبــة‪ -‬تأجيــل تنفيــذ احلكــم لكــون املدعــى‬\n               ‫عليــه طالب ـ ًا ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                               ‫‪ -1‬املادة (‪ )218‬من نظام اإلجراءات اجلزائية‪.‬‬\n    ‫‪ -2‬املــواد (‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                ‫العقليــة‪.‬‬\n\n\n\n    ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n    ‫بقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن‬\n    ‫الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وباملقتضــى‬\n    ‫الشــرعي لتعاطــي احلشــيش املخــدر‪ ،‬حيــث إنــه مت تفتيشــه فعثــر معــه‬\n    ‫علــى ســيجارتني غيــر مدخنــة حتتــوي علــى مــادة احلشــيش املخــدر وأثبــت‬\n    ‫التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n    ‫املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪،‬‬\n    ‫حيــث إن املدعــى عليــه طالــب وال يوجــد لــه ســوابق والكميــة احملــازة‬\n    ‫قليلــة‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه‬\n\n‫‪5‬‬\n\f‫وقــررت جلــده ثمانــن جلــدة دفعــة واحــدة لتعاطــي احلشــيش وســجنه ملــدة‬\n‫ثالثــة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني مــع تأجيــل‬\n‫تنفيــذ احلكــم إلــى وقــت اإلجــازة املدرســية تطبيقـ ًا حلكــم املــادة (‪)218‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة وقنــع املدعــى عليــه باحلكــم وعــارض‬\n‫املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                      ‫احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/5/20‬ه ـ لــدي أنــا‬\n‫‪ .....‬رئيــس احملكمــة اجلزائيــة بالدمــام وبنــاء علــى املعاملــة الــواردة إلينــا‬\n‫من هيئة التحقيق واالدعاء العام باملنطقة الشرقية برقم ‪ 13284‬وتاريخ‬\n‫‪1429/5/15‬ه ـ واملقيــدة لدينــا برقــم ‪ 299970‬وتاريــخ ‪1429/5/16‬ه ـ‬\n‫واحملالــة لنــا برقــم ‪ 2403‬وتاريــخ ‪1429/5/16‬ه ـ عليه قدم املدعي العام‬\n‫ا فيهــا أدعــي علــى ‪ .....‬ســعودي مبوجــب الســجل املدنــي رقــم‬     ‫دعــواه قائـ ً‬\n‫‪ ....................‬بأنــه يف يــوم االثنــن املوافــق ‪1429/4/29‬ه ـ وأثنــاء إقامــة‬\n‫إحــدى الدوريــات األمنيــة لنقطــة تفتيــش بحــي االتصــاالت بالدمــام مت‬\n‫اســتيقاف ســيارة مــن نــوع ‪ .....‬بقيــادة املدعــى عليــه املذكــور وبتفتيشــه‬\n‫شــخصيا عثــر معــه داخــل جيــب بنطالــه األيســر علــى علبــة ســجائر‬\n‫تبــن أن بداخلهــا ســيجارتان ملفوفتــان غيــر مدخنــة بلــغ وزنهمــا ‪2.2‬‬\n‫جــم جرامــان واثنــان مــن العشــرة مــن اجلــرام أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي رقــم ‪........‬وتاريــخ ‪1429/5/2‬ه ـ احتوائهما على مادة احلشــيش‬\n‫املخــدر وباســتجوابه أقــر بصحــة واقعــة القبــض وبعائديــة ســيجارتي‬\n‫احلشــيش املخــدر املضبوطــة لــه شــخصيا بقصــد التعاطــي مضيفــا بأنــه‬\n\n                                                                                         ‫‪6‬‬\n\f    ‫يتعاطــى احلشــيش املخــدر مــن أربعــة أشــهر وآخــر مــرة تعاطــى فيهــا‬\n    ‫احلشــيش املخــدر قبــل أربعــة أيــام مــن القبــض عليــه وأســفر التحقيــق‬\n    ‫عــن اتهامــه بحيــازة ســيجارتني ملفوفتــن غيــر مدخنتــن تزنــان ‪ 2.2‬جــم‬\n    ‫جرامــان واثنــان مــن العشــرة مــن اجلــرام حتتويــان علــى مــادة احلشــيش‬\n    ‫املخــدر بقصــد التعاطــي وتعاطيــه لــذات النــوع وذلــك لألدلــة والقرائــن‬\n    ‫التاليــة‪ -1:‬اعترافــه حتقيقــا مبــا نــوه عنــه واملــدون علــى الصفحتــن‬\n    ‫رقــم‪ 2-1‬مــن ملــف التحقيــق رقــم ‪-2 .2‬محضــر تنفيــذ املهمــة املنــوه عنــه‬\n    ‫املرفــق علــى اللفــة رقــم ‪ -3 2‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه‬\n    ‫واملرفــق علــى اللفــة رقــم ‪ 12‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو‬\n    ‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا أطلــب‬\n    ‫مــا يلــي‪:‬أو ًال اثبــات مــا أســند إليــه وفــق الفقــرة رقــم ‪ 2‬مــن املــادة رقــم ‪3‬‬\n    ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا‬\n    ‫يلــي ‪ 1‬عقوبــة الســجن الــواردة بالفقــرة رقــم ‪ 1‬مــن املــادة رقــم ‪ 41‬مــن‬\n    ‫النظــام ‪ -2‬منعــه مــن الســفر وفقــا للفقــرة رقــم ‪ 1‬مــن املــادة رقــم‪56‬‬\n    ‫مــن النظــام ‪ -3‬باملقتضــى الشــرعي العترافــه بتعاطــي مــادة احلشــيش‬\n    ‫املخــدر ثانيــا إعمــال مقتضــى املــادة ‪ 218‬مــن نظــام اإلجــراءات اجلزائيــة‬\n    ‫كــون املذكــور طالــب هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n    ‫عليــه قــال مــا ذكــره املدعــي العــام مــن حيــازة ســيجارتني ملفوفتــن غيــر‬\n    ‫مدخنتــن تزنــان جرامــان واثنــان مــن العشــرة مــن اجلــرام حتتويــان علــى‬\n    ‫احلشــيش املخــدر بقصــد التعاطــي وتعاطــي احلشــيش كل ذلــك صحيــح‬\n    ‫وأنــا نــادم علــى مــا فعلــت هكــذا أجــاب وقــد جــرى منــا االطــاع علــى‬\n    ‫التقريــر الكيمــاوي الشــرعي رقــم ‪........‬يف ‪1429/5/2‬ه ـ املتضمــن‬\n    ‫احتــواء الســيجارتني مــادة احلشــيش املخــدر كمــا جــرى منــا االطــاع‬\n\n\n‫‪7‬‬\n\f‫علــى صحيفــة ســوابق املدعــى عليــه فوجدتهــا خاليــة فبنــاء علــى مــا‬\n‫تقــدم وحيــث أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام لــذا‬\n‫فقــد قــررت اآلتــي‪:‬أوال ثبــت لــدي إدانــة املدعــى عليــه بحيــازة ســيجارتني‬\n‫ملفوفتــن غيــر مدخنتــن تزنــان جرامــان واثنــان مــن العشــرة مــن اجلــرام‬\n‫حتتويــان علــى حشــيش مخــدر بقصــد التعاطــي وتعاطــي احلشــيش ثانيـ ًا‬\n‫إعمــال املــادة ‪ 41‬مــن نظــام املكافحــة مــع مراعــاة املــادة‪ 60‬مــن النظــام‬\n‫لقلــة الكميــة وخلــو صحيفــة ســوابق املدعــى عليــه ولكونــه طالــب‬\n‫بســجنه ثالثــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة ويكــون‬\n‫التنفيــذ يف عطلــة املــدارس مراعــاة للمــادة ‪ 218‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة وجلــده ثمانــون جلــدة علنــا دفعــة واحــدة لتعاطــي احلشــيش ثالثـاً‪:‬‬\n‫إعمــال املــدة ‪ 56‬مــن نظــام املكافحــة مبنــع املدعــى عليــه مــن الســفر‬\n‫ملــدة ســنتني تبــدأ بعــد خروجــه مــن الســجن وبذلــك حكمــت للحــق العــام‬\n‫وبعــرض احلكــم علــى الطرفــن قنــع املدعــى عليــه أمــا املدعــي العــام‬\n‫فقــرر االعتــراض بالئحــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/20‬هــ‪ .‬احلمــد هلل وحــده‬\n‫وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/6/27‬ه ـ افتتحــت اجللســة يف‬\n‫متــام الســاعة التاســعة وخمــس وأربعــون دقيقــة حيــث وردتنــا املعاملــة‬\n‫املتعلقــة بدعــوى املدعــي العــام ضــد مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية برقــم ‪ 341413959‬وتاريــخ ‪1434/6/21‬ه ـ وبرفقهــا القــرار‬\n‫رقــم ‪ 34241010‬وتاريــخ ‪1434/6/14‬ه ـ واملتضمــن املصادقــة علــى‬\n‫احلكــم وقــد أغلقــت اجللســة يف متــام الســاعة العاشــرة‪ .‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                             ‫‪1434/06/27‬ه ـ ‪.‬‬\n\n\n                                                                                      ‫‪8‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":5,"source_page_end":8,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa5a5023166b475eced28abf9e55d7eb27573d4277b68cacefc0aa521d550c12","normalized_text_hash":"f7a7f76166336c4467950020035402d4860e28c5a63a1add8ae5c1fbe3975c16","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p5-3412799"},{"id":"cba3a0d7-1017-5306-8a6f-a3a9610da936","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -سيجارة بها حشيش -رجوع عن اإلقرار بالتعاطي -تعزير للتهمة القوية - إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد واملنع من السفر -تأجيل محاكمة الغائب يف دعوى جزائية -تأجيل محاكمة الغائب.","document_number":"34185966","case_number":"31742","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/13","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -سيجارة بها حشيش -رجوع عن اإلقرار بالتعاطي -تعزير للتهمة القوية - إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد واملنع من السفر -تأجيل محاكمة الغائب يف دعوى جزائية -تأجيل محاكمة الغائب.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪ 34185966:‬تاريخه ‪1434/04/13 :‬هـ‬\n                            ‫رقم الدعوى ‪31742 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34215476‬تاريخه‪1434/05/19:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬ســيجارة بهــا‬\n     ‫حشــيش ‪ -‬رجــوع عــن اإلقــرار بالتعاطــي ‪ -‬تعزيــر للتهمــة القويــة ‪-‬‬\n     ‫إثبــات بالشــهادة ‪ -‬إدانــة باحليــازة املجــردة عــن القصــد ‪ -‬تعزيــر‬\n     ‫بالســجن واجللــد واملنــع مــن الســفر‪ -‬تأجيــل محاكمــة الغائــب يف‬\n                              ‫دعــوى جزائيــة ‪ -‬تأجيــل محاكمــة الغائــب‪.‬‬\n\n\n\n     ‫املــواد (‪ )39‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n\n     ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانتهمــا‬\n     ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي‪ ،‬واحلكــم عليهمــا بعقوبــة‬\n     ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا املدعــى عليــه الثانــي فعثــر‬\n     ‫فيهــا علــى ســيجارة مــن احلشــيش ومت تفتيــش األول شــخصيا فعثر بجيبه‬\n     ‫علــى قطعــة يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر الكيميائــي‬\n     ‫الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬اعتــرف املدعــى‬\n     ‫عليــه األول أمــام جهــة التحقيــق بتعاطــي احلشــيش املخــدر‪ ،‬أنكــر‬\n\n‫‪9‬‬\n\f‫األول أمــام احملكمــة مــا أســنده إليــه املدعــي العــام فيمــا لــم يحضــر‬\n‫الثانــي‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع‬\n‫شــهادة شــهود محضــر القبــض فشــهدوا بضبــط قطعــة احلشــيش املخــدر‬\n‫يف جيــب األول‪ ،‬حكمــت احملكمــة بصــرف النظــر عــن تطبيــق املــادة‬\n‫(‪ )41‬بحــق املدعــى عليــه األول وقضــت بإدانتــه بحيــازة احلشــيش املخــدر‬\n‫حيــازة مجــردة وقــررت ســجنه ملــدة تســعة أشــهر ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني‪ ،‬كمــا قــررت جلــده ســبعني جلــدة دفعــة واحــدة‬\n‫وأخــذ التعهــد عليــه بعــدم العــود لقــاء توجــه التهمــة لــه بتعاطــي احلشــيش‬\n‫املخــدر كمــا قــررت تأجيــل محاكمــة الثانــي حتــى حضوره‪،‬عــارض‬\n‫املدعــي العــام واملدعــى عليــه األول علــى احلكــم‪ ،‬قــررت محكمــة‬\n                                         ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل‪ /‬املكلــف برقــم ‪ 31742‬وتاريــخ ‪ 1431/10/17‬ه ـ‬      ‫ّ‬\n‫املقيــدة باحملكمــة برقــم ‪ 312129‬وتاريــخ ‪ 1431/09/27‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1434/03/18‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n‫الثانيــة عشــرة والنصــف وفيهــا حضــر املدعــي العــام ‪ /‬وادعــى علــى كل‬\n‫مــن ‪ ......./ 1‬ســعودي بالســجل رقــم (‪ ........ /2 ).....‬ســعودي بالســجل‬\n‫رقــم (‪ )........‬قائــا يف حتريــر دعــواه عليــه ( فإنــه باالطــاع علــى‬\n‫محضــر القبــض والتفتيــش املعــد مــن قبــل مكافحــة املخــدرات مبنطقــة‬\n‫حائــل املتضمــن أنــه يف الســاعة السادســة مســاء بتاريــخ ‪1431/8/1‬ه ـ‬\n\n                                                                                      ‫‪10‬‬\n\f     ‫حتركــت ســيارة مــن نــوع ‪ ......‬رقــم اللوحــة (‪ )....‬مــن أحــد األماكــن‬\n     ‫املشــبوهة بقيــادة املتهــم الثانــي يرافقــه املتهــم األول وبتفتيــش املتهــم‬\n     ‫األول عثــر بجيــب البنطلــون األيســر علــى قطعــة تــزن ( ‪ )3‬جرامــات‬\n     ‫يشــتبه أن تكــون مــن احلشــيش املخــدر وبتفتيــش الثانــي شــخصيا لــم‬\n     ‫يعثــر علــى ممنــوع وبتفتيــش الســيارة عثــر بالقــرب مــن ناقــل احلركــة‬\n     ‫علــى ســيجارة ملفوفــة لفــا يدويــا تــزن (‪ )1‬جــرام واحــدا يشــتبه أن‬\n     ‫تكــون مخلوطــة مبــادة احلشــيش املخــدر ومت اإلفــراج عنهمــا اســتناد ًا‬\n     ‫للمــادة ( ‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة وبســماع أقــوال املتهــم‬\n     ‫االول أنكــر عالقتــه مبــا ضبــط بحوزتــه وأفــاد بــأن املضبــوط بحوزتــه‬\n     ‫يعــود لزميلــه املتهــم الثانــي وأفــاد بأنــه يســتعمل احلشــيش املخــدر منــذ‬\n     ‫شــهر وباســتجواب املتهــم الثانــي أقــر بعائديــة مــا ضبــط لــه مــكان يف‬\n     ‫الســيارة ومــا ضبــط بحــوزة املتهــم األول بقصــد التعاطــي وأنــه يتعاطــى‬\n     ‫احلشــيش املخــدر منــذ ســنة وأن القطعــة التــي ضبطــت بجيــب بنطلــون‬\n     ‫زميلــه املتهــم األول كانــت ملتصقــة باجلــوال وليــس لزميلــه عالقــة بهــا‬\n     ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪ )941‬الصــادر مــن‬\n     ‫املركــز اإلقليمــي ملراقبــة الســموم مبنطقــة القصيــم برقــم (‪/1684‬م س‬\n     ‫‪ )45/65/‬وتاريــخ ‪1431/8/19‬ه ـ إيجابيــة عينــة القطعــة ملــادة احلشــيش‬\n     ‫املخــدر وإيجابيــة الســيجارة املضبوطــة ملــادة احلشــيش املخــدر وملــا أشــير‬\n     ‫إليــه أقــرر اتهــام كال مــن ‪1‬ـ بإحــراز قطعــة تــزن (‪ )3‬ثــاث جرامــات مــن‬\n     ‫مــادة احلشــيش املخــدر‪ .‬واتهــام ‪2‬ـ بحيــازة قطعــة تــزن ( ‪ )3‬ثــاث جرامــات‬\n     ‫مــن مــادة احلشــيش املخــدر وســيجارة مخلوطــة مبــادة احلشــيش املخــدر‬\n     ‫تــزن ( ‪ )1‬جرامــا واحــدا بقصــد التعاطــي ‪ ،‬املجــرم مبوجــب الفقــرة‬\n     ‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n\n\n‫‪11‬‬\n\f‫العقليــة الصــادر باملرســوم امللكــي رقــم ( م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وقيــام املتهــم األول بتعاطــي احلشــيش املخــدر يف الســابق املجــرم شــرعاً‪.‬‬\n‫وحيــث إن مــا أقدمــا عليــه فعــل محــرم ومعاقــب عليــه شــرعا ونظامــا‬\n‫ممــا يتعــن إحالتهمــا إلــى احملكمــة اجلزائيــة إلثبــات إدانــة األول بإحــراز‬\n‫قطعــة تــزن (‪ )3‬ثــاث جرامــات مــن مــادة احلشــيش املخــدر‪ ،‬وتعاطيــه‬\n‫الســابق للحشــيش املخــدر وإثبــات إدانــة املتهــم الثانــي بحيــازة الزايــد‬\n‫بحيــازة قطعــة تــزن (‪ )3‬ثــاث جرامــات مــن مــادة احلشــيش املخــدر‬\n‫وســيجارة مخلوطــة مبــادة احلشــيش املخــدر تــزن (‪ )1‬جرامــا واحــدا‬\n‫بقصــد التعاطــي ‪ ،‬وتعاطيــه الســابق للحشــيش املخــدر واحلكــم عليهمــا‬\n‫مبــا يلــي‪1 :‬ـ الســجن ‪2‬ـ املنــع مــن الســفر اســتنادا للمــواد (‪)62،56،41‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‪ ،‬وبــاهلل‬\n‫التوفيــق) أ‪.‬هــ‪ .‬هكــذا ادعــى ويف هــذه اجللســة حضر املدعــى عليه األول‬\n‫ولــم يحضــر املدعــى عليــه الثانــي ثــم قــرر املدعــي العــام بقولــه‪ :‬أطلــب‬\n‫احلكــم علــى املدعــى عليــه األول وتأجيــل احلكــم علــى املدعــى عليــه‬\n‫الثانــي حتــى حضــوره‪ .‬هكــذا قــرر وبعــرض دعــوى املدعــي العــام علــى‬\n‫املدعــى عليــه األول أجــاب بقولــه‪ :‬غيــر صحيــح جملــة وتفصيــا‪ .‬هكــذا‬\n‫أجــاب ثــم ســألت املدعــي العــام هــل لديــك زيــادة بينــة غيــر مــا قدمــت ؟‬\n‫قــال‪ :‬ال ســوى مــا وجــد يف أوراق املعاملــة وشــهادة معــدي احملضــر وأطلب‬\n‫رفــع اجللســة إلحضارهــم وســماع مــا لديهــم مــن شــهادة ‪ ،‬فأجيــب لطلبــه‬\n‫وقــررت رفــع اجللســة حتــى حضــور معــدي احملضــر وســماع مــا لديهــم مــن‬\n‫شــهادة‪ ،‬وعليــه جــرى التوقيــع‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه واحضــر املدعــي العــام للشــهادة وأدائهــا كل‬\n‫من ‪1‬ـ ‪ .....‬ســعودي اجلنســية بالســجل رقم (‪ )...‬و ‪2‬ـ ‪ .....‬ســعودي بالســجل‬\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫رقــم (‪ ).....‬ولــدى استشــهادهما شــهد كل واحــد منهمــا بانفــراده قائــا‪:‬‬\n     ‫أشــهد بــاهلل تعالــى أن مــا جــاء باحملضــر صحيــح مطابــق للوقــع وأشــهد‬\n     ‫بــاهلل تعالــى إنــي وجــدت يف جيــب بنطلــون املدعــى عليــه ‪ .....‬األيســر‬\n     ‫قطعــة صغيــرة يشــتبه أن تكــون مــن احلشــيش املخــدر هكــذا شــهد‬\n     ‫كل واحــد منهمــا بانفــراده ‪ ،‬ثــم طلبــت مــن املدعــي العــام مزكيــن‬\n     ‫لشــاهديه فاحضــر للشــهادة وأدائهــا كل مــن ‪1‬ـ ســعودي بالســجل رقــم‬\n     ‫(‪ ).....‬و‪2‬ـ‪ .....‬ســعودي بالســجل رقــم (‪ ).....‬ولــدى استشــهادهما شــهد‬\n     ‫كل واحــد منهمــا بانفــراده قائــا‪( :‬أشــهد بــاهلل تعالــى إن الشــاهدين‬\n     ‫ثقتــن وعدلــن وال اعــرف عنهمــا إال اخليــر) هكــذا شــهد كل واحــد‬\n     ‫منهمــا بانفــراده‪ ،‬ولعــدم حضــور املدعــى عليــه رفعــت اجللســة ‪،‬وعليــه‬\n     ‫جــرى التوقيــع‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام وحضــر حلضــوره‬\n     ‫املدعــى عليــه األول ‪ .....‬ســعودي بالســجل رقــم (‪ ).....‬وبعــرض الشــهود‬\n     ‫ومــا شــهدوا بــه علــى املدعــى عليــه األول أجــاب بقولــه‪ :‬أمــا الشــهود‬\n     ‫فــا اعرفهــم وأمــا مــا جــاء يف الشــهادة فغيــر صحيــح‪ .‬هكــذا أجــاب‬\n     ‫ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة ومــن ضمنهــا التقريــر‬\n     ‫الكيميائــي الشــرعي رقــم ( ‪ )941‬الصــادر مــن املركــز اإلقليمــي‬\n     ‫ملراقبــة الســموم مبنطقــة القصيــم برقــم (‪/1684‬م س ‪ )45/65/‬وتاريــخ‬\n     ‫‪1431/8/19‬ه ـ املتضمــن إيجابيــة عينــة القطعــة ملــادة احلشــيش املخــدر‬\n     ‫وإيجابيــة الســيجارة املضبوطــة ملــادة احلشــيش املخــدر واملــدون علــى‬\n     ‫لفــة رقــم (‪ ،)21‬ثــم جــرى االطــاع علــى اعتــراف املدعــى عليــه حتقيقــا‬\n     ‫واملــدون علــى لفــة رقــم (‪ )1‬صحيفــة رقــم (‪ )3‬املتضمــن (اعتــراف املدعــى‬\n     ‫عليــه باســتعمال احلشــيش املخــدر منــذ مــدة شــهر تقريبــا) وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه أجــاب بقولــه‪ :‬غيــر صحيــح‪ .‬هكــذا أجــاب ثــم جــرى‬\n\n\n‫‪13‬‬\n\f‫االطــاع علــى الســجل اجلنائــي الصادر بحق املدعــى عليه األول املتضمن‬\n‫وجــود ســابقة مخــدرات مســجلة بحقــه وبعــرض ذلــك علــى املدعــى عليــه‬\n‫األول أجــاب بقولــه‪ :‬صحيــح‪ .‬فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n‫وملــا جــاء يف شــهادة الشــهود املعدلــن حســب األصــول الشــرعية وملــا جــاء‬\n‫يف التقريــر الكيميائــي الشــرعي وملــا تقــدم يف أوراق املعاملــة لذلــك‬\n‫كلــه قــررت مــا يلــي‪ :‬أوال ـ صرفــت النظــر عــن تطبيــق املــادة ‪ 41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لعــدم انطباقهــا بحــق‬\n‫املدعــى عليــه‪ .‬ثانيــا ـ ثبــت لــدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن‬\n‫احلشــيش املخــدر تــزن ( ‪ )3‬جرامــات لــم يتبــن لــي قصــد املدعــى عليــه‬\n‫مــن حيازتهــا وملــا ظهــر لــي مــن حــال املدعــى عليــه وبنــاء علــى املــواد‬\n‫(‪ )60،56،39‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة قــررت‬\n‫تعزيــره علــى ذلــك مبــا يلــي‪ :‬أ) ســجنه ملــدة تســعة أشــهر ابتــداء مــن تاريــخ‬\n‫إيقافــه بهــذه القضيــة‪ .‬ب) منعــه مــن الســفر ملــدة ســنتني خــارج اململكــة‬\n‫بعــد انتهــاء مــدة محكوميــة ســجنه‪ .‬ثالثــا ـ توجهــت لــدي التهمــة بحــق‬\n‫املدعــى عليــه األول بتعاطيــه احلشــيش املخــدر وقــررت تعزيــره علــى ذلــك‬\n‫مبــا يلــي‪ :‬أ) جلــده ســبعني جلــدة دفعــة واحــدة‪ .‬ب) أخــذ التعهــد الشــديد‬\n‫عليــه بعــدم العــودة ملثــل هــذه األمــور‪ .‬هــذا مــا ظهــر لــي وبــه حكمــت‬\n‫كمــا قــررت تأجيــل احلكــم علــى املدعــى عليــه الثانــي حتــى حضــوره‪.‬‬\n‫وبعــرض احلكــم علــى املدعــي العــام لــم يقنــع بــه وطلــب رفعــه حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة‪ .‬وبعرضــه علــى املدعــى عليــه األول‬\n‫لــم يقنــع بــه وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة‪.‬‬\n‫فجــرى تســليمه نســخة مــن القــرار الشــرعي إلبــداء معارضتــه عليــه يف‬\n‫مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ هذا اليــوم الســبت ‪1434/4/13‬هـ‬\n\n\n                                                                                         ‫‪14‬‬\n\f     ‫‪ ،‬وجــرى إفهامــه بأنــه إن تأخــر عــن ذلــك ســقط حقــه يف االعتــراض‬\n     ‫وســترفع املعاملــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــة ففهــم‬\n     ‫ذلــك وعليــه جــرى التوقيــع‪ .‬مت قفــل اجللســة يف متــام الســاعة العاشــرة‬\n     ‫والنصــف مــن هــذا اليــوم الســبت املوافــق ‪1434/4/13‬هــ‪ .‬واهلل املوفــق‬\n                              ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n     ‫املختصــة بتدقيــق القضايــا اجلزائية مبحكمة االســتئناف مبنطقة حائل‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبنطقــة‬\n     ‫حائــل برقــم ‪ 34776306‬يف تاريــخ ‪1434/5/14‬ه ـ املرفــق بهــا القــرار‬\n     ‫الشــرعي الصــادر مــن صاحــب الفضيلــة الشــيخ ‪ ................./‬القاضــي‬\n     ‫باحملكمــة اجلزائيــة بحائــل برقــم ‪ 34185966‬وتاريــخ ‪1434/4/13‬ه ـ‬\n     ‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪ .................../1‬ســعودي‬\n     ‫بالســجل املدنــي رقــم (‪ .............../2 ).............‬ســعودي بالســجل املدنــي‬\n     ‫رقــم (‪ ).............‬بشــأن حيــازة مخــدرات وقــد تضمــن القــرار حكــم‬\n     ‫صاحــب الفضيلــة وفقــه اهلل علــى املدعــى عليهمــا علــى النحــو املفصل يف‬\n     ‫القــرار املرفــق وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة ‪ :‬جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه بالقــرار‬\n     ‫املشــار إليــه ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                 ‫وســلم ‪.‬‬\n\n\n\n\n‫‪15‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":9,"source_page_end":15,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"287ba7a941bd8d574e99d19702bb5e61fd8c0a25d639310538d78704bef13b61","normalized_text_hash":"3196dd32300a6419f48d775457d516b31f0c6164c45b735187b07c208c436921","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p9-34185966"},{"id":"b62cd80f-e7bf-5099-96f8-a8af74e6184d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وقيادة السيارة حتت تأثيرها -إدانة -نزول عن احلد األدنى للعقوبة- التعزير باجللد والسجن واملنع من السفر.","document_number":"342627","case_number":"341820","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/03","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وقيادة السيارة حتت تأثيرها -إدانة -نزول عن احلد األدنى للعقوبة- التعزير باجللد والسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 342627:‬تاريخه‪1434/01/03 :‬هـ‬\n                     ‫رقم الدعوى‪341820:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3434371‬تاريخه‪1434/02/10 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا وقيــادة‬\n‫الســيارة حتــت تأثيرهــا‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪-‬‬\n                        ‫التعزيــر باجللــد والســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n  ‫‪ -1‬قول اهلل تعالى‪ (( :‬وال تلقوا بأيديكم إلى التهلكة )) البقرة‪.195:‬‬\n                ‫‪ -2‬املادتان (‪ )128‬و (‪ )131‬من نظام اإلجراءات اجلزائية‪.‬‬\n‫‪ -3‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬واملــادة (‪ )41‬واملــادة (‪ )56‬واملــادة (‪ )60‬مــن‬\n                            ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫‪ -4‬الفقرة (‪ )8‬من جدول املخالفات رقم (‪ )1‬امللحق بنظام املرور‪.‬‬\n ‫‪ -5‬الفقرة (‪ )2‬من قرار مجلس الوزراء رقم (‪ )315‬يف ‪1428/10/24‬هـ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة حبــوب‬\n‫الكبتاجــون بقصــد التعاطــي وتعاطيــه لهــا وقيادتــه الســيارة حتــت‬\n‫تأثيرهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبتــه لقــاء‬\n‫قيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة تقــرر مــن اجلهــة املختصــة‬\n‫حيــث إنــه مت تفتيــش املدعــى عليــه شــخصيا فعثــر يف محفظتــه علــى‬\n\n                                                                                      ‫‪16‬‬\n\f     ‫حبــوب محظــورة وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة‬\n     ‫املرســلة ملــادة الكبتاجــون‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه‬\n     ‫املدعــي العــام ودفــع بأنــه لــم يكــن يعلــم بــأن هــذه احلبــوب محظــورة ومــن‬\n     ‫ـاء امتنــاع اإلعــذار باجلهــل بالنظــام يف مثــل حالــة املدعــى‬  ‫املقــرر قضـ ً‬\n     ‫عليــه‪ ،‬وحيــث إن املدعــى عليــه ال توجــد لــه ســوابق والكميــة احملــازة‬\n     ‫قليلــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى عليــه‬\n     ‫بجميــع مــا نســب إليــه وقــررت جلــده ســتني جلــدة دفعــة واحــدة وســجنه‬\n     ‫ملــدة ثالثــن يومـ ًا ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني وإفهامــه‬\n     ‫بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة تقــرر‬\n     ‫مــن اجلهــة املختصــة وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                ‫عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬رئيــس احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪341820‬‬\n     ‫وتاريــخ ‪1434/01/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 347490‬وتاريــخ‬\n     ‫‪1434/01/03‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/01/20‬ه ـ حضــر‬\n     ‫املدعــي العــام ‪ ........‬كمــا حضــر املدعــى عليــه ‪ .....‬ســعودي رقــم‬\n     ‫ســجله املدنــي (‪ ).....‬وقــدم األول الئحــة دعــوى تتضمــن أنــه بتاريــخ‬\n     ‫‪1427/10/3‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل رجــال األمــن‬\n     ‫أثنــاء قيادتــه ســيارته وكان يرافقــه شــخص آخــر (مت اإلفــراج عنــه‬\n     ‫حيــث ثبــت عــدم صلتــه بالقضيــة) وبتفتيــش املتهــم املذكــور عثــر‬\n     ‫يف محفظتــه علــى عــدد (‪ )4‬أربــع حبــات اثبــت التقريــر الكيمــاوي‬\n\n‫‪17‬‬\n\f‫الشــرعي رقــم(‪ )........‬إيجابيــة احلبــوب املضبوطــة ملــادة الكبتاجــون‬\n‫املنبهــة واحملظــورة‪ ،‬وباســتجواب املتهــم أقــر بصحــة واقعــة القبــض وأن‬\n‫مــا ضبــط معــه عائــد لــه بقصــد التعاطــي كمــا أقــر بتعاطــي احلبــوب‬\n‫املنبهــة واحملظــورة وليــس لزميلــه عالقــة مبــا ضبــط معــه وال علــم لــه‬\n‫بذلــك كمــا أقــر أنــه قــام بقيــادة الســيارة بعــد التعاطــي حبــوب املنبهــة‬\n‫واحملظــورة‪ .‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n‫مســجلة‪ .‬أطلــب مــن فضيلتكــم إثبــات مــا أســند عليــه وفق ـ ًا للفقــرة‬\n‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واحلكــم عليــه‬\n‫مبــا يلــي‪-1 :‬العقوبــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن‬\n‫النظــام‪-2 .‬إعمــال مقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام‪.‬‬\n‫‪-3‬التصــرف يف املــواد املخــدرة املضبوطــة وفق ـ ًا للفقرتــن (‪ )2.1‬مــن‬\n‫املــادة (‪ )52‬مــن النظــام‪-4 .‬إثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر‬\n‫احلبــوب املنبهــة احملضــورة وإفهامــه بــأن عقابــه علــى ذلــك عائــد لولــي‬\n‫ا مــا‬‫األمــر‪ .‬هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ املذكــور وأنــه عثــر‬\n‫بحوزتــي علــى (‪ )4‬أربــع حبــات منبهــة محظــورة وأن قصــدي مــن حيازتهــا‬\n‫التعاطــي وأننــي تعاطيــت واحــدة منهــا وقــدت الســيارة وأنا حتــت تأثيرها‬\n‫كل ذلــك صحيــح لكننــي لــم أكــن أعلــم أنهــا حبــوب منبهــة محظــورة‬\n‫وقــد أخبرنــي مــن أعطانــي إياهــا أنهــا حبــوب منشــطة هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــي العــام قــال إن املدعــى عليــه كان يعلــم أنهــا‬\n‫حبــوب محظــورة بدليــل اعترافــه بذلــك يف محاضــر التحقيــق وبتصفــح‬\n‫املعاملــة جــرى االطــاع علــى محضــر اســتجواب املدعــى عليــه املــدون‬\n‫علــى ص (‪ )1‬ملــف مرفــق لفــة (‪ )1‬فوجدتهــا يتضمــن‪ :‬س‪ /‬ملــن تعــود تلــك‬\n\n\n                                                                                       ‫‪18‬‬\n\f     ‫احلبــوب؟ ج‪/‬ال أعلــم س‪/‬أنــت مــراوغ أنصحــك بقــول احلقيقــة؟ ج‪/‬كنــت‬\n     ‫ألعــب كــورة يف حــي ‪........‬ووضعــت محفظتــي مــع شــباب ومــن احملتمــل‬\n     ‫أن يكــون وضعهــا أحــد يف محفظتــي كمــا جــرى االطــاع على محضر‬\n     ‫إقــرار املدعــى عليــه املــدون علــى ص (‪ )1‬ملــف مرفــق لفــة (‪ )14‬فوجدتــه‬\n     ‫يتضمــن مــا نصــه‪ :‬مت القبــض علــي مــن قبــل أمــن الطــرق وقــد عثــر‬\n     ‫بحوزتــي علــى مــا عدده(‪)4‬أربــع حبــات مــن حبــوب الكبتاجــون وهــي‬\n     ‫عائــدة لــي بقصــد التعاطــي وقــد تعاطيــت حبــة واحــدة قبــل القبــض علــي‬\n     ‫يف منزلــي وهــي املــرة األولــى واألخيــرة واإلقــرار مذيــل باســم املدعــى‬\n     ‫عليــه وبصمــة وبعــرض ذلــك علــى املدعــى عليــه قــال أنكــرت أو ًال أمــام‬\n     ‫رجــال املكافحــة خوف ـ ًا مــن العقوبــة ثــم أقــررت أمــام هيئــة التحقيــق‬\n     ‫وأخبــرت احملقــق مبــا ذكرتــه أنف ـ ًا مــن ظنــي أنهــا منشــطات رياضيــة‬\n     ‫لكنــه لــم يكتــب ذلــك يف اإلقــرار فجــرى ســؤال الطرفــن ألديهمــا‬\n     ‫مــا يــرد أن إضافتــه فقــال املدعــي العــام ليــس مــا لــدي مــا أضيفــه وقــال‬\n     ‫املدعــى عليــه إننــي مصــاب بفقــر الــدم الوراثــي ويف جلســة أخــرى بتاريــخ‬\n     ‫‪1434/01/26‬ه ـ حضــر املدعــي العــام كمــا حضــر املدعــى عليــه فبنــاء‬\n     ‫علــى مــا تقــدم وحيــث تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى‬\n     ‫عليــه بتعاطــي احلبــوب املنبهــة احملظــورة وحيــازة أربــع حبــات منهــا‬\n     ‫بقصــد التعاطــي وقيــادة الســيارة حتــت تأثيــر احلبــوب املنبهــة احملظــورة‬\n     ‫وألن هــذه احملكمــة مختصــه بنظــر هــذه الدعــوى بنــاء علــى املــواد‬\n     ‫(‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار املدعــى عليــه وهــو‬\n     ‫بكامــل أهليتــه بحيــازة أربــع حبــات منبهــة محظــورة بقصــد التعاطــي‬\n     ‫وتعاطــي حبــة منبهــة محظــورة وقيــادة الســيارة حتــت تأثيرهــا وألن مــا‬\n     ‫دفــع بــه مــن جهلــه بــأن هــذه احلبــوب محظــورة ال ينفــي توافــر القصــد‬\n\n\n‫‪19‬‬\n\f‫اجلنائــي لديــه فهــو عاقــل بالــغ مــن ســكان البلــد واألنظمــة اجلزائيــة‬\n‫الصــادرة واملنشــورة يف اجلريــدة الرســمية يفتــرض مــن الكافــة العلــم‬\n‫ـاء امتنــاع اإلعــذار باجلهــل بالنظــام يف‬   ‫بهــا ومــن املبــادئ املســتقرة قضـ ً‬\n‫مثــل حالــة املدعــى عليــه كمــا أن املدعــى عليــه أقــر بعلمــه بأنهــا حبــوب‬\n‫منشــطة وأقــر حتقيقـ ًا أمــام دائــرة التحقيــق واالدعــاء العــام بأنهــا حبــوب‬\n‫كبتاجــون ممــا يــدل علــى معرفتــه بهــا وألن مــا دفــع بــه مــن جهلــه بأنهــا‬\n‫حبــوب محظــورة ظاهــر االختــاق بدليــل تناقــض أقوالــه أمــام جهــات‬\n‫التحقيــق يف عائديــة احلبــوب لــه لهــذا كلــه وألن مــا أقــدم عليــه مــن‬\n‫حيــازة وتعاطــي احلبــوب املنبهــة احملظــورة أفعــال محرمــة شــرع ًا ملــا يف‬\n‫تعاطــي هــذه احلبــوب املنبهــة مــن أضــرار صحيــة بالغــة واهلل تعالــى يقــول‬\n‫((وال تلقــوا بأيديكــم إلــى التهلكــة)) البقرة‪195:‬كمــا أن حيــازة‬\n‫وتعاطــي هــذه احلبــوب احملظــورة مجــرم نظام ـ ًا وفق ـ ًا للفقــرة (‪ )2‬مــن‬\n‫املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات كمــا أن قيــادة الســيارة حتــت‬\n‫تأثيــر هــذه احلبــوب احملظــورة مجــرم نظامـ ًا وفقـ ًا للفقــرة (‪ )8‬مــن جــدول‬\n‫املخالفــات رقــم (‪)1‬امللحــق بنظــام املــرور فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليــه احلاضــر باآلتــي أوالً‪ :‬تعاطــي احلبــوب املنبهة احملظــورة ثانياً‪ :‬حيازة‬\n‫أربــع حبــات منبهــة محظــورة بقصــد التعاطــي ثالثـاً‪ :‬قيــادة الســيارة حتــت‬\n‫تأثيــر احلبــوب املنبهــة احملظــورة ونظــرا لقلــة الكميــة ولعــدم وجــود‬\n‫ســوابق علــى املدعــى عليــه وبنــاء علــى املــواد(‪ )60،56،41‬مــن نظــام‬\n‫مكافحــة املخــدرات فقــد حكمــت علــى املدعــى عليــه باآلتــي‪ :‬جلــده‬\n‫ســتني جلــده دفعــة واحــدة و ســجنه ثالثــن يومـ ًا ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن تعزيــر ًا‬\n‫لــه علــى التعاطــي واحليــازة وأفهمتــه بــأن عقوبتــه علــى قيــادة الســيارة‬\n\n\n                                                                                        ‫‪20‬‬\n\f     ‫حتــت تأثيــر احلبــوب احملظــورة تقــرر مــن اجلهــة املختصــة وفــق الفقــرة‬\n     ‫(‪ )2‬مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ وبإعــان‬\n     ‫احلكــم قنــع بــه املدعــى عليــه وقــرر املدعــي العــام اعتراضــه وطلــب رفــع‬\n     ‫املعاملــة حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة‪ ،‬وصلــى‬\n     ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد‬\n     ‫فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف فقــد عــادت‬\n     ‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n     ‫رقــم ‪ 3434371‬يف ‪1434/2/10‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n                                                ‫وللبيــان احلــق يف ‪1434/2/20‬هــ‪.‬‬\n\n\n\n\n‫‪21‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":16,"source_page_end":21,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14c2def677f934b51d52cb07aa5347819da18352a8fbbd79a8c97732cd2e4c13","normalized_text_hash":"069f0ce0e90d8f960427d265ec450ea98e32edddf51ac156ae9c696e1f94ca15","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p16-342627"},{"id":"c7aaf2c5-e420-57d2-ad93-8ff5cccd2968","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حد املسكر -إقرار -إدانة -تداخل احلدود -االكتفاء بحد املسكر عن العقوبة التعزيرية للتعاطي -التعزير بالسجن واملنع من السفر.","document_number":"3412095","case_number":"349518","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/14","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حد املسكر -إقرار -إدانة -تداخل احلدود -االكتفاء بحد املسكر عن العقوبة التعزيرية للتعاطي -التعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3412095 :‬تاريخه‪1434/01/14 :‬هـ‬\n                      ‫رقم الدعوى‪349518:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3412095‬تاريخه‪1434/01/14 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n‫وتعاطيهــا ‪ -‬حــد املســكر ‪ -‬إقــرار ‪ -‬إدانــة ‪ -‬تداخــل احلــدود ‪ -‬االكتفــاء‬\n‫بحــد املســكر عــن العقوبــة التعزيريــة للتعاطــي ‪ -‬التعزيــر بالســجن‬\n                                                         ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n  ‫‪ -1‬قول اهلل تعالى‪(( :‬وال تقتلوا النفس التي حرم اهلل إال باحلق))‪.‬‬\n         ‫‪ -2‬قول اهلل تعالى‪(( :‬وال تفسدوا يف األرض بعد إصالحها ))‪.‬‬\n‫‪ -3‬املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                            ‫واملؤثــرات العقلية‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــربه املســكر وحيــازة احلبــوب‬\n‫احملظــورة واحلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬واحلكــم‬\n‫عليــه بحــد املســكر وبعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيــش املدعــى‬\n‫عليــه شــخصيا فضبــط بجيــب ثوبــه األيســر علــى حبــوب محظــورة‪،‬‬\n‫كمــا مت تفتيــش منزلــه فعثــر فيــه علــى كيــس نايلــون بداخلــه عــدد مــن‬\n‫احلبــوب احملظــورة‪ ،‬وعثــر فيــه أيضـ ًا علــى قطعــة مــن احلشــيش املخــدر‪،‬‬\n\n                                                                                    ‫‪22‬‬\n\f     ‫وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n     ‫املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي‬\n     ‫العــام‪ ،‬كمــا أقـ َّـر بشــرب املســكر وباســتعمال احلشــيش املخــدر ممــا‬\n     ‫يســتوجب االكتفــاء بحــد واحــدٍ كمــا أقـ َّـر بتعاطــي احلبــوب احملظــورة‬\n     ‫فيتوجــه االكتفــاء عــن مجازاتــه لقــاء ذلــك بحــد املســكر‪ ،‬قضــت‬\n     ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت إقامــة‬\n     ‫حــد املســكر عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا وســجنه‬\n     ‫ملــدة تســعة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬قنــع‬\n     ‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة‬\n                                               ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫ـدي‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n     ‫ـاء علــى املعاملــة‬\n                        ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n     ‫برقــم ‪ 238‬وتاريــخ ‪1434/01/06‬ه ـ واملقيــدة بهــذه احملكمــة‬\n     ‫برقم‪3443390‬وتاريــخ ‪1434/01/06‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n     ‫الرئيــس برقــم ‪ 349518‬وتاريــخ ‪1434/01/06‬ه ـ فتحــت اجللســة األولــى‬\n     ‫يــوم األربعــاء ‪1434/01/14‬ه ـ الســاعة احلاديــة عشــرة والنصــف وفيهــا‬\n     ‫حضــر املدعــي العــام امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n     ‫خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعاء العام مبحافظة األحســاء‬\n     ‫ا بصفتــي‬   ‫ذي الرقــم ‪ ........‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n     ‫مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‪:‬‬\n\n‫‪23‬‬\n\f‫البالــغ مــن العمر(‪)46‬عامــا ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم (‪ ).....‬موظف بـ ‪ ،.....‬محصن‪ ،‬قبض عليه بتاريخ ‪1433/11/26‬هـ‬\n‫أوقــف مبوجــب أمــر التوقيــف الصــادر مــن دائــرة التحقيــق واالدعــاء‬\n‫العــام باألحســاء رقــم (‪ )........‬وتاريــخ ‪1433/11/27‬ه ـ اســتناد ًا لبرقيــة‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )79425/4/5/1‬وتاريــخ‬\n‫‪1432/12/20‬ه ـ وجــرى متديــد إيقافــه (‪ )25‬يومــا مبوجــب أمــر التمديــد‬\n‫الصــادر مــن رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام باملنطقــة‬\n‫الشــرقية رقــم (‪ )........‬وتاريــخ ‪1433/11/ 29‬ه ـ وأحيــل إلــى الســجن‬\n‫العــام مبحافظــة األحســاء انــه بتاريــخ ‪1433/11/26‬ه ـ مت القبــض عليه‬\n‫مــن قبــل إحــدى فــرق مكافحــة املخــدرات مبحافظــة األحســاء إثــر توفــر‬\n‫معلومــات عــن حيــازة املدعــى عليــه للحبــوب احملظــورة مبحطــة ‪،........‬‬\n‫ا علــى قدميــه‬    ‫وبانتقــال الفرقــة هنــاك شــوهد املدعــى عليــه مترج ـ ً‬\n‫فتــم اســتيقافه وبتفتيشــه ضبــط بجيــب ثوبــه األيســر علــى (‪ )1.5‬حبــة‬\n‫ونصــف احلبــة بيضــاء اللــون يشــتبه أن تكــون مــن احلبــوب احملظــورة ‪،‬‬\n‫وباالنتقــال ملنزلــه وتفتيشــه عثــر باملجلــس علــى كيــس نايلــون بداخلــه‬\n‫عــدد (‪ )43‬ثالثــة وأربعــن حبــة يشــتبه أن تكــون مــن احلبــوب احملظــورة‬\n‫مخبئــة بداخــل إحــدى املســاند‪ ،‬كمــا عثــر أيض ـ ًا علــى قطعــة ســمراء‬\n‫اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪0.6‬جــم)‬\n‫ســتة مــن العشــرة مــن اجلــرام وقــد أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫رقــم (‪ )........‬لعــام ‪1433‬ه ـ إيجابيــة العينــة املرســلة ملركبــات احلشــيش‬\n‫املخــدر ومركبــات اإلمفيتامــن احملظــور واملدرجــان مــن ضمــن املــواد‬\n‫يف اجلــدول (‪ )1‬فئــة (أ) و(‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وباســتجوابه اعتــرف بشــراء وحيــازة عــدد (‪)44.5‬‬\n\n\n                                                                                  ‫‪24‬‬\n\f     ‫أربــع وأربعــن حبــة ونصــف احلبــة مــن حبــوب اإلمفيتامــن احملظــور ‪،‬‬\n     ‫وقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪0.6‬جــم) ســتة مــن العشــرة مــن‬\n     ‫اجلــرام بقصــد التعاطــي وتعاطيــه لنوعيهــا‪ ،‬وشــرب املســكر وقــد أســفر‬\n     ‫التحقيــق عــن توجيــه االتهــام لــه بشــرب املســكر ‪ ،‬وحيازة عــدد (‪)44.5‬‬\n     ‫أربــع وأربعــن حبــة ونصــف احلبــة مــن حبــوب اإلمفيتامــن احملظــور ‪،‬‬\n     ‫وقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪0.6‬جــم) ســتة مــن العشــرة‬\n     ‫مــن اجلــرام بقصــد التعاطــي وتعاطيــه لنوعيهــا‪ ،‬وذلــك لألدلــة والقرائــن‬\n     ‫التالية‪-1 :‬اعترافه املنوه عنه املدون على الصفحة رقم (‪ )2/1‬من دفتر‬\n     ‫التحقيــق املرفــق علــى اللفــة رقــم (‪ -2 .)13‬محضــر القبــض املــدون على‬\n     ‫الصفحــة رقــم (‪ )12/11‬مــن ملــف إجــراءات االســتدالل األوليــة املرفــق‬\n     ‫علــى اللفــة رقــم (‪ -3 .)4‬التقريــر الكيمــاوي املرفــق علــى اللفــة رقــم‬\n     ‫(‪ .)26‬وببحــث ســوابقه تبــن وجــود ســابقه مخــدرات يف عــام ‪1431‬ه ـ ‪.‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n     ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n     ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ اطلــب‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ .1 -:‬بحــد املســكر لقــاء‬\n     ‫شــربه لــه‪ .2 .‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء حيازتــه للحبــوب‬\n     ‫احملظــورة واحلشــيش املخــدر (املوصــوف يف الدعــوى) بقصــد التعاطــي‬\n     ‫وتعاطيــه لنوعيهــا‪ .3 .‬منــع مــن الســفر خــارج البــاد وفقـ ًا للفقــرة األولــى‬\n     ‫مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه هكــذا ا َّدعــى ؛ عليــه فقد حضر‬\n     ‫املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي‬\n\n\n‫‪25‬‬\n\f‫العــام عليــه فأجــاب قائـاً‪ :‬صحيــح مــا نســبه لــي املدعــي العــام مــن واقعــة‬\n‫القبــض ومــن حيازتــي لعــدد (‪ )44.5‬أربعــة وأربعــن حبــة ونصــف احلبــة‬\n‫مــن حبــوب اإلمفيتامــن املخــدر ومــن حيازتــي لقطعــة احلشــيش املخــدر‬\n‫البالــغ وزنهــا (‪0،6‬جــم) ســتة مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n‫ومــن اســتعمالي للحشــيش املخــدر وللحب ــوب احملظــورة ومــن شــربي‬\n‫للمســكر مختــار ًا عاملـ ًا بتحرميــه وصحيــح اعتــرايف ونســبة الســابقة لــي‬\n‫وقــد أخــذت محكوميتهــا هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى‬\n‫التقريــر الكيمــاوي الشــرعي الصــادر مــن قســم الكيميــاء الشــرعية‬\n‫باملركــز اإلقليمــي ملراقبــة الســموم التابــع للمديريــة العامــة للشــؤون‬\n‫الصحيــة باملنطقــة الشــرقية برقــم ( ‪ )........‬لعــام ‪1433‬ه ـ املتضمــن‬\n‫إيجابيــة عي ــنة مــا ضبــط للحشــيش املخــدر وللحبــوب احملظــورة كمــا‬\n‫جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن وجــود ســابقة‬\n‫مخــدرات واحــدة عليــه فبنــاء علــى مــا ورد مــن الدعــوى واإلجابــة وبعــد‬\n‫النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا ورد يف محضــر‬\n‫القبــض واعتــراف املدعــي عليــه ومبــا أنــه صــادق علــى صحــة مــا نســب‬\n‫إليــه مــن حيــازة احلشــيش املخــدر واحلبــوب احملظــورة علــى صفــة مــا ورد‬\n‫يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة مــن اخلطــر والضــرر علــى البــاد والعبــاد‬\n‫وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل‬\n‫إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا يســتوجب‬\n‫معاقبــة املدعــى عليــه وتعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة‬\n‫واألربعــن مــن نظــام مكافحــة املخــدرات كمــا يتوجــه اســتحقاقه‬\n‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة األولــى منهــا ومبــا‬\n\n\n                                                                                       ‫‪26‬‬\n\f     ‫أن املدعــى عليــه أقـ َّـر بشــرب املســكر وحــد املســكر أن يجلــد صاحبــه‬        ‫َّ‬\n     ‫ثمانــن جلــدة علنــا كمــا اســتقر عليــه عمــل األمــة ممــا يتوجــب حــد‬\n     ‫املدعــى عليــه حــد املســكر ومبــا أنــه أقـ َّـر باســتعمال احلشــيش املخــدر‬\n     ‫واســتعماله يأخــذ حكــم املســكر للتوافــق بينهمــا يف منــاط احلكــم‬\n     ‫الســتعماله للحشــيش املخــدر ممــا يســتوجب االكتفــاء بحــد واحــدٍ ملــا‬\n     ‫قــرره أهــل العلــم مــن االكتفــاء بحـ ِّـد واحــد يف حــال اجتماعهمــا إذا‬\n     ‫كانــا مــن جنــس واحــد كمــا يتوجــه االكتفــاء عــن مجازاتــه عــن‬\n     ‫اســتعمال احلبــوب لدخــول األصغــر يف حكــم األكبــر لــذا كلــه وألجــل‬\n     ‫ـدي إدانــة‬‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n     ‫ـدي‬\n      ‫املدعــى عليــه بشــرب املســكر مختــار ًا عامل ـ ًا بتحرميــه كمــا ثبــت لـ َّ‬\n     ‫إدانتــه أيض ـ ًا باســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن‬\n     ‫ـدي إدانتــه كذلــك باســتعمال‬       ‫جلــدة دفعــة واحــدة علن ـ ًا كمــا ثبــت لـ َّ‬\n     ‫احلبــوب احملظــورة وعقوبتــه لقــاء ذلــك داخلــة يف احلــد ثاني ـاً‪ /‬ثبــت لــدي‬\n     ‫إدانــة املدعــى عليــه بحيــازة لعــدد (‪ )44.5‬أربعــة وأربعــن حبــة ونصــف‬\n     ‫احلبــة مــن حبــوب اإلمفيتامــن املخــدر ومــن حيــازة لقطعــة احلشــيش‬\n     ‫املخــدر البالــغ وزنهــا (‪0،6‬جــم) ســتة مــن العشــرة مــن اجلــرام بقصــد‬\n     ‫التعاطــي وأن يعــزر بســجنه تســعة أشــهر مــن تاريــخ توقيفــه علــى ذمــة‬\n     ‫القضيــة وذلــك مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة‬\n     ‫املخــدرات‪ .‬ثالثــا‪ /‬وأن مينــع مــن الســفر مــدة عامــن حســب مقتضــى مــا‬\n     ‫ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه علــى أن يكــون‬\n     ‫املنــع ابتــداء مــن انتهــاء محكوميتــه وبتــاوة احلكــم علــى الطرفــن‬\n     ‫وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب‬\n     ‫املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي‬\n\n\n‫‪27‬‬\n\f‫الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك‬\n‫حرمــة اســتعمال احلشــيش املخــدر و احلبــوب احملظــورة وأثرهمــا الســيئ‬\n‫علــى العقــل واملــال وأقفلــت اجللســة الســاعة الثانيــة عشــرة وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف‬\n                                                               ‫‪1434/01/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد ففــي‬\n‫يــوم االربعاء‪1434/04/17‬ه ـ فتحــت اجللســة الثانيــة وقــد عــادت‬\n‫املعاملــة املتعلقــة بالدعــوى العامــة املقامــة ضــد‪ .......‬يف قضيــة مخــدرات‬\n‫مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب فضيلــة‬\n‫رئيســها ذي الرقــم ‪ 34195526‬والتاريــخ ‪1434/04/10‬ه ـ مرفق ـ ًا بهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثالثيــة األولــى رقــم‬\n‫‪/3449444‬ج‪ 1‬وتاريــخ ‪1434/02/27‬ه ـ وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ :‬وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة لوحــظ أن املعاملــة خاصــة بدعــوى املدعــي‬\n‫العــام ضــد‪ .......‬يف حــن أن خطــاب فضيلتــه رقــم ‪ 3443390‬يف‬\n‫‪1434/1/20‬ه ـ خــاص بدعــوى املدعــي العــام ضــد ‪ .......‬كمــا لوحــظ‬\n‫أن هنــاك قــرار رقــم ‪ 3412131‬يف ‪1434/1/14‬ه ـ مرفــق باملعاملــة ليــس‬\n‫لــه عالقــة بهــذه املعاملــة ملالحظــة مــا ذكــر وإكمــال الــازم ومــن ثــم‬\n‫إعــادة املعاملــة وبــاهلل التوفيــق قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‪،‬‬\n‫قاضــي اســتئناف‪ .......‬ختمــه وتوقيعــه رئيــس الدائــرة‪ .......‬ختمــه وتوقيعــه‬\n‫أ‪ .‬ه ـ عليــه أجيــب مشــايخي بأنــه قــد مت إكمــال الــازم حيــال تعديــل‬\n‫اخلطــاب وأقفلــت اجللســة وصلــى اهلل وسـلّم علــى نبينــا محمــد وعلــى آلــه‬\n                           ‫وصحبــه أجمعــن حتريــر ًا يف ‪1434/04/17‬هــ‪.‬‬\n\n\n                                                                                    ‫‪28‬‬\n\f     ‫احلمــد هلل وحــده وبعــد وقــد مت تصديــق احلكــم من محكمة االســتئناف‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم ‪.‬‬\n\n\n\n\n‫‪29‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":22,"source_page_end":29,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c04e5d22e560ba2ad29c2be3bdc08dc7336517dcb8de7f7c35f9d810dcf5c161","normalized_text_hash":"3ebdb42e219397b07011199562ff32c803802ab6ecfbe0866ccc4e245fcc232d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p22-3412095"},{"id":"135d0e0d-8dd7-5933-9866-1e64b7dab418","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة هيروين بقصد الترويج واالجتار وترويجه يف السابق وتستر على مصدره -مقاومة رجال األمن والهرب منهم - إقرار -إدانة -تعزير بالسجن واجللد والغرامة -مصادرة وإبعاد .","document_number":"3435848","case_number":"349858","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/06","year":"1434","subject":"مخدرات -حيازة هيروين بقصد الترويج واالجتار وترويجه يف السابق وتستر على مصدره -مقاومة رجال األمن والهرب منهم - إقرار -إدانة -تعزير بالسجن واجللد والغرامة -مصادرة وإبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3435848:‬تاريخه‪1434/01/06 :‬هـ‬\n                      ‫رقم الدعوى‪349858:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34295786‬تاريخه‪1434/08/13:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة هيرويــن بقصــد الترويــج واالجتــار وترويجــه يف‬\n‫الســابق وتســتر علــى مصــدره ‪ -‬مقاومــة رجــال األمــن والهــرب منهــم ‪-‬‬\n‫إقــرار‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ‪ -‬مصــادرة وإبعــاد ‪.‬‬\n\n\n\n\n       ‫املواد (‪ )38‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة الهيرويــن املخــدر بقصــد الترويــج واالجتــار وترويجــه يف‬\n‫الســابق ومقاومتــه للفرقــة القابضــة وهربــه منهــا وتســتره علــى مصــدر‬\n‫املخدر‪،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملصــادرة‬\n‫واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬مت االتفــاق معــه علــى شــراء نصــف كبســولة هيرويــن فوافــق‬\n‫علــى ذلــك وطلــب متريــر أرقــام بطاقــات شــحن اجلــوال مســبقة الدفــع‬\n‫فتــم القبــض عليــه وبتفتيشــه عثــر معــه علــى الهيرويــن ومبلــغ مالــي‬\n‫وبتفتيــش الغرفــة التــي يســكنها مبفــرده عثــر فيهــا علــى الهيرويــن‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للهيرويــن‬\n‫املخــدر‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬قضــت‬\n\n                                                                                ‫‪30‬‬\n\f     ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت ســجنه‬\n     ‫ملــدة ســت ســنوات وجلــده ســتمائة جلــدة مفرقــة علــى اثنتــي عشــرة دفعــة‬\n     ‫وتغرميــه مبلــغ ألــف ريــال وإبعــاده عــن البــاد بعــد تنفيــذ عقوبــة ســجنه‬\n     ‫ومصــادرة املضبوطــات‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n         ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالريــاض برقــم ‪ 349858‬وتاريــخ ‪1434/01/06‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 3444780‬وتاريــخ ‪1434/01/06‬ه ـ ففــي يــوم األحــد‬\n     ‫املوافق‪1434/02/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 :30‬وفيهــا‬\n     ‫حضــر املدعــي العــام وادعــى علــى ‪ .........‬البالــغ مــن العمــر (‪ )26‬عام ـاًـ‬\n     ‫‪ .......‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪،)...........‬‬\n     ‫أعــزب‪ ،‬متعلــم‪ ،‬متســبب‪ ،‬يقيــم مبدينــة الريــاض‪ ،‬أوقــف بتاريــخ‬\n     ‫‪1433/11/21‬هــ‪ ،‬وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة‬\n     ‫ومتديــد التوقيــف رقــم (ه ـ را‪ )5/‬وتاريــخ ‪1433/11/‬هــ‪ .‬حيــث انه بتاريخ‬\n     ‫‪1433/11/21‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق إدارة‬\n     ‫العمليــات التابعــة لــإدارة العامــة ملكافحــة املخــدرات مبنطقــة الريــاض‬\n     ‫وذلــك بنــاء علــى ورود معلومــات عــن طريــق احــد مصادرهــم الســرية‬\n     ‫عــن وجــود شــخص باكســتاني اجلنســية يدعــى ‪ ........‬يقــوم بترويــج‬\n     ‫كبســوالت الهيرويــن املخــدر عــن طريــق متريــر أرقــام بطاقــات شــحن‬\n     ‫اجلــوال مســبوقة الدفــع ‪ .......‬ويعاونــه شــخص باكســتاني يدعــى‪..........‬‬\n\n‫‪31‬‬\n\f‫وهــو املذكــور يســكن بغرفــة عــزاب بحــي ‪ ....‬حيــث يقــوم برمــي‬\n‫كبســوالت الهيرويــن املخــدر املتعاطــي هــذه املــادة وذلــك بتوجيــه مــن‬\n‫املدعــو‪ ....... /‬بعــد ذلــك قــام املصــدر الســري باالتصــال علــى املدعــو‪/‬‬\n‫‪ .........‬وطلــب منــه نصــف كبســولة هيرويــن حيــث طلــب املدعــو‪.......... /‬‬\n‫مــن املصــدر الســري مبلــغ وقــدره (‪ )2500‬ألفــان وخمســمائة وطلــب مــن‬\n‫املصــدر الســري أن يقــوم بشــراء بطاقــات شــحن اجلــوال مســبوقة الدفــع‬\n‫‪ .......‬مببلــغ ألفــان وخمســمائة ريــال ومتريــر أرقــام هــذه البطاقــات باملبلــغ‬\n‫املتفــق عليــه للمدعــو‪ ........... /‬وطلــب مــن املصــدر الســري التواجــد بحــي‬\n‫‪ ..........‬وبعــد مراقبــة غرفــة املدعــو‪ ............ /‬خــرج مــن الغرفــة وقــام‬\n‫بالــدوران داخــل احلــارات الضيقــة فتقــرر ضبطــه وبضبطــه اتضــح انــه‬\n‫يدعــى‪ ........./‬باكســتاني اجلنســية وبتفتيشــه عثــر بداخــل جيبــه األميــن‬\n‫علــى كيــس بداخلــه كبســولتني بيضاويــة الشــكل مماثلــة لــم يتــم‬\n‫تهريبــه عــن طريــق األحشــاء يشــتبه أن تكــون ملــادة الهيرويــن املخــدر‬\n‫النقــي بلــغ وزنهــا (‪ )14.5‬أربعــة عشــر جرام ـ ًا وخمســة أعشــار اجلــرام‬\n‫وعثــر بداخــل جيبــه األيســر علــى منديــل بداخلــه نصــف كبســولة بهــا‬\n‫مســحوق يشــتبه أن تكــون ملــادة الهيرويــن املخــدر بلــغ وزنهــا (‪)3.3‬‬\n‫ثالثــة جرامــات وثالثــة أعشــار اجلــرام وعثــر معــه علــى مفاتيــح للغرفــة‬\n‫التــي يســكن فيهــا وعثــر كذلــك علــى جهازيــن جــوال األول يحمــل‬\n‫الرقــم املصنعــي (‪ )........‬يحمــل الرقــم (‪ )...........‬والثانــي يحمــل الرقــم‬\n‫املصنعــي (‪ )........‬يحمــل الرقــم (‪ )........‬وعثــر معــه علــى مبلــغ وقــدره‬\n‫(‪ )123‬مائــة وثالثــة وعشــرون ريــا ًال ومبناقشــته مــن قبــل الفرقــة‬\n‫القابضــة عــن الهيرويــن املضبــوط بحوزتــه اقــر أمامنــا بحضــور مترجــم‬\n‫اإلدارة انــه يقــوم بترويــج الهيرويــن املخــدر لصالــح املدعــو‪ ......../‬وذلــك‬\n\n\n                                                                                        ‫‪32‬‬\n\f     ‫برميــه يف أماكــن محــدودة ملتعاطــي هــذه املــادة واقــر بــأن املدعــو‪......./‬‬\n     ‫طلــب منــه رمــي نصــف كبســولة هيرويــن علمـ ًا بــأن املصــدر الســري لــم‬\n     ‫يقــوم بتمريــر أرقــام بطاقــات شــحن اجلــوال مســبوقة الدفــع ‪ .......‬باملبلــغ‬\n     ‫الــذي طلــب املدعــو‪ ......./‬وقــدره (‪ )2500‬ألفــان وخمســمائة ريــال‬\n     ‫وذلــك بإيعــاز مــن الفرقــة القابضــة لكــون املبلــغ كبيــر وبســؤالنا عــن‬\n     ‫ســكنه اقــر بوجــود كبســوالت هيرويــن بداخــل الغرفــة التــي يســكنها‬\n     ‫مبفــرده واســتناد ًا للمــادة (‪ )43‬مــن نظــام اإلجــراءات اجلزائيــة مت فتــح‬\n     ‫الغرفــة التــي يســكنها وبتفتيــش الغرفــة عثــر داخــل دورة امليــاه فــوق‬\n     ‫ســخان املــاء علــى كيــس بداخلــه مــا عــدده تســع كبســوالت بيضاويــة‬\n     ‫الشــكل مماثلــة ملــا يتــم تهريبــه عــن طريــق األحشــاء يشــتبه أن تكــون‬\n     ‫املــادة الهيرويــن املخــدر النقــي بلــغ وزنهــا (‪ )67.5‬ســبعة وســتون جرامــات‬\n     ‫ونصــف اجلــرام ولــم يعثــر معــه علــى محظــورات أخــرى وبســؤالنا عــن‬\n     ‫املدعــو‪ .......‬ذكــر لنــا انــه لــم يســبق أن قابلــه وانــه يتواجــد يف مدينــة‬\n     ‫جــدة وال يعــرف لــه ســكناً‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n     ‫بالريــاض املرفــق رقــم (‪ ).......‬لعــام ‪1433‬ه ـ إيجابيــة املســحوق يف‬\n     ‫الكبســوالت ونصــف الكبســولة للهيرويــن وهــو مــن املــواد املخــدرة‬\n     ‫واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة‪ .‬وبســماع أقوالــه األوليــة اقــر بحيــازة كبســولة واحدة‬\n     ‫وأن حيازتــه للجميــع القصــد لكســب مــادي مقابــل (‪ )50‬ريــال‪ .‬وقــد‬\n     ‫أســفرت إجــراءات التحقيــق معــه عــن توجيــه االتهــام لــ‪ ........ /‬بارتكاب‬\n     ‫جرميــة حيــازة (‪ )11.5‬إحــدى عشــرة كبســولة ونصــف الكبســولة مــن‬\n     ‫الهيرويــن املخــدر بقصــد الترويــج واالجتــار وبترويجــه كبســوالت‬\n\n\n‫‪33‬‬\n\f‫الهيرويــن يف الســابق املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومقاومتــه الفرقــة القابضــة وهربــه منهــا‬\n‫وتســتره علــى مصــدر الكميــة املروجــة املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ )1 :‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه‬\n‫ا علــى الصفحــات رقــم (‪ ).....‬مــن ملــف‬       ‫األوليــة املنــوه عنــه املــدون تفصيـ ً‬\n‫إجــراءات االســتدالل املرفــق لفــه رقــم (‪ )2 .) ......‬مــا تضمنــه محضــر‬\n‫القبــض املنــوه عنــه املــدون علــى الصفحــة رقــم ( )‪ )3 .‬مــا تضمنــه التقرير‬\n‫الكيميائــي الشــرعي املرفــق لفــه رقــم ( ‪ .)...‬وببحــث ســوابقه لــم يعثــر‬\n‫له على أي ســابقة مســجله بحقه حتى تاريخه‪ .‬وحيث أن ما أق ــدم عل ــيه‬\n‫ال ــمذكور ف ــعل م ــحرم شــرع ًا وم ــعاقب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب‬\n‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪ )1 :‬بعقوبــة الســجن‬\n‫واجللــد والغرامــة املاليــة بحقــه وفق ـ ًا للمــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة املشــار إليــه وأعمــال الفقــرة (األولــى) مــن‬\n‫املــادة (‪ )62‬مــن ذات النظــام لقــاء مــا اســند إليــه‪ )2 .‬منعــه مــن الســفر‬\n‫إلــى خــارج اململكــة بعــد تنفيــذ عقوبتــه وفقـ ًا للفقــرة (األولــى) مــن املــادة‬\n‫(‪ )56‬مــن نفــس النظــام املشــار إليــه‪ )3 .‬مصــادرة جهــازي الهاتــف اجلــوال‬\n‫الــذي يحمــان الرقــم املصنعــي (‪ ).......‬ورقــم (‪ ).......‬الســتخدامها يف‬\n‫اجلرميــة اســتناد ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة‪ )4 .‬إلغــاء شــريحتي اجلــوال املســتخدمتان‬\n‫يف عمليــة الترويــج ذاتــي الرقــم (‪ ).......‬ورقــم (‪ ).......‬وعــدم صرفهــا‬\n‫لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ الشــركة‬\n‫مصــدرة الشــريحة بذلــك اســتناد ًا إلــى تعميــم ســمو وزيــر الداخليــة رقــم‬\n\n\n                                                                                             ‫‪34‬‬\n\f     ‫(‪ )9798‬وتاريــخ ‪1428/2/10-9‬هــ‪ .‬وبــاهلل التوفيــق هــذا وباســتجواب‬\n     ‫املدعــى عليــه فأجــاب علــى لســان مترجــم احملكمــة بقولــه مــا ذكــره‬\n     ‫املدعــي العــام يف دعــواه صحيــح جملــه وتفصيــا فقــد مت القبــض علــي‬\n     ‫وبتفتيشــي عثــر يف جيبــي األميــن علــى كيــس بداخلــه كبســولتني‬\n     ‫بداخلهمــا هرويــن كمــا عثــر يف جيبــي األيســر علــى منديــل بداخلــه‬\n     ‫نصــف كبســوله بهــا هرويــن وبتفتيــش غرفتــي عثــر بداخــل دوره امليــاه‬\n     ‫فيهــا علــى كيــس بداخله تســع كبســوالت بها هروين وأنــا أقوم بترويج‬\n     ‫الهرويــن املخــدر لصالــح املدعــو ‪ ......‬وذلــك برميــه يف أمــكان محــدودة‬\n     ‫ملتعاطــي هــذه املــادة ويتــم التنســيق بذلــك عــن طريــق جوالــي املذكوريــن‬\n     ‫يف الدعــوى هــذا كمــا جــرى االطــاع علــى املعاملــة ووجــدت التقريــر‬\n     ‫الكيميائــي الشــرعي رقــم ‪/10805‬س واملتضمــن ثبــوت إيجابيــة‬\n     ‫العينــات املرســلة للهيروين‪.‬أهــ‪ .‬فنظــرا ملــا تقــدم مــن الدعــوى واإلجابــة‬\n     ‫وحيــث صــادق املدعــى عليــه علــى مــا جــاء يف دعــوى املدعــي العــام فقــد‬\n     ‫ثبــت لــدي ادنتــه بحيــازة إحــدى عشــرة كبســوله ونصــف الكبســولة‬\n     ‫مــن الهيرويــن املخــدر بلــغ وزنهــا (‪85,3‬جــم) بقصــد الترويــج واالجتــار‬\n     ‫ونظــرا لعــدم وجــود ســوابق عليــه وال فائــدة مــن طــول ســجنه لكونــه‬\n     ‫اجنبــي فقــد حكمــت عليــه تعزيــرا بســجنه ملــده ســت ســنوات اعتبــارا‬\n     ‫مــن تاريــخ توقيفــه وبجلــده ســتمائة جلــده مفرقــه علــى ثنتــي عشــرة‬\n     ‫فتــرة متســاوية بــن كل فتــره وأخــرى أســبوعان وبدفــع غرامــه قدرهــا‬\n     ‫ألــف ريــال وبإبعــاده خلــارج اململكــة بعــد تنفيــذ عقوبــة ســجنه متشــيا مــع‬\n     ‫املادتــن (‪ )56-38‬مــن نظــام مكافحــه املخــدرات ومبصــادره جواليــه‬\n     ‫املذكوريــن مــع إلغــاء شــريحتيهما ‪ ،‬هــذا وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه فقــرر قناعتــه بذلــك أمــا املدعــى العــام فقــرر عــدم القناعــة معتبــرا‬\n\n\n‫‪35‬‬\n\f‫الئحــة الدعــوى الئحــة اعتراضيــة علــى احلكــم وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/02/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ 341363074‬وتاريــخ ‪1434/7/4‬ه ـ‬\n‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‬\n‫‪ .................‬برقــم ‪ 3435848‬وتاريــخ ‪1434/1/12‬ه ـ واخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪ ...................‬جنســيته (باكســتاني)‪ ،‬موضوعهــا‬\n‫مخــدرات‪ ،‬وبعــد التدقيــق يف إجابــة فضيلــة ناظــر القضيــة وفقــه اهلل‬\n‫علــى قــرار محكمــة االســتئناف الســابق تقــرر املصادقــة علــى احلكــم‬\n‫لعــدم موجــب املالحظــة ‪ ،‬مــع تنبيــه فضيلتــه علــى أن دعــوى املدعــي‬\n‫العــام ذكــر فيهــا أن املدعــى عليــه ســعودي وهــو باكســتاني اجلنســية ‪،‬‬\n‫ثــم طالــب مبنعــه مــن الســفر ‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪36‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":30,"source_page_end":36,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2790f4f5db067cafd95a9a1bc1c62e33526b74526ea7a72f19e290f089f73af7","normalized_text_hash":"42f73676528c4648e8ca0a6215a1d0ac656bbb7f72f0226651aa38dccc47c4b2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p30-3435848"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
